CREATE TABLE "dcops_t14_raw" ("id" INT NOT NULL PRIMARY KEY, "note" VARCHAR(64) NULL);
INSERT INTO "dcops_t14_raw" ("id", "note") VALUES (1, 'a;b');
INSERT INTO "dcops_t14_raw" ("id", "note") VALUES (2, 'it''s ok');
